import {categories,brand,brands,kinds} from './catalog.mjs?v=5';
import {money,cartTotal} from './core.mjs?v=5';
export const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',heart:'<path d="M20.8 4.9a5.5 5.5 0 0 0-7.8 0L12 6l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 22l8.8-9.3a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V5a3 3 0 0 1 6 0v3"/>',menu:'<path d="M3 7h18M3 12h18M3 17h18"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2.5"/><circle cx="15" cy="17" r="2.5"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',chevron:'<path d="m6 9 6 6 6-6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',box:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V8M12 13v10M7 5.8l9 5"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
// Enquadramento: fotos quase quadradas preenchem a moldura; as demais aparecem inteiras sobre um fundo desfocado da própria foto.
export const fitClass=(w,h)=>{const r=(Number(w)||1)/(Number(h)||1);return r>.86&&r<1.18?'fit-cover':'fit-contain'};
const bgStyle=src=>`--bg:url('${esc(src)}')`;
export function productCard(p,favorites=[]){const alt=p.gallery?.[1];const on=favorites.includes(p.id);const n=p.gallery?.length||1;return `<article class="product-card"><div class="product-image ${p.demo?'demo-photo':'catalog-photo'} ${fitClass(p.imageWidth,p.imageHeight)}" style="${bgStyle(p.image)}"><a href="#/produto/${esc(p.id)}" aria-label="Ver ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)} na cor ${esc(p.color)} — ${p.demo?'imagem ilustrativa':'foto do catálogo'}" loading="lazy" decoding="async" width="${p.imageWidth||720}" height="${p.imageHeight||720}">${alt?`<img class="product-alt ${fitClass(alt.width,alt.height)}" src="${esc(alt.image)}" alt="" loading="lazy" decoding="async">`:""}</a><span class="product-badge ${p.stock===0?'soldout':''}">${p.demo?'EXEMPLO':'L&T SELECTED'}</span>${n>1?`<span class="photo-count" aria-hidden="true">${n} fotos</span>`:''}<button class="heart-button ${on?'active':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="${on?'Remover dos':'Adicionar aos'} favoritos: ${esc(p.name)}" aria-pressed="${on}">${icon('heart')}</button><a href="#/produto/${esc(p.id)}" class="quick-view" tabindex="-1">${p.stock===null?'Ver detalhes':p.stock?'Escolher tamanho':'Ver produto'} ${icon('plus')}</a></div><div class="product-info"><span class="product-brand">${esc(p.brand)}</span><h3><a href="#/produto/${esc(p.id)}">${esc(p.name)}</a></h3><div class="product-price-row"><span>${money(p.price)}</span><span class="product-swatch" style="--swatch:${esc(p.hex)}" title="${esc(p.color)}"><span class="sr-only">${esc(p.color)}</span></span></div><span class="product-color">${esc(p.color)}</span></div></article>`}
const categoryTabs=(current='todos')=>`<nav class="category-tabs" aria-label="Categorias">${categories.map(c=>`<a href="#/colecao/${c.id}" class="${c.id===current?'selected':''}" ${c.id===current?'aria-current="page"':''}>${c.name}</a>`).join('')}</nav>`;
// Foto de um produto pelo índice da galeria, com o enquadramento certo.
const shot=(p,i=0,cls='',eager=false)=>{const g=p.gallery?.[i]||{image:p.image,width:p.imageWidth,height:p.imageHeight};return `<span class="shot ${fitClass(g.width,g.height)} ${cls}" style="${bgStyle(g.image)}"><img src="${esc(g.image)}" alt="${esc(p.name)} — ${esc(p.brand)}" width="${g.width||900}" height="${g.height||900}" ${eager?'':'loading="lazy"'} decoding="async"></span>`};
export function homeView(products,favorites){
const pick=id=>products.find(p=>p.id===id)||products[0];
const catalog=products.filter(p=>!p.demo);
const garments=['rl-polo','rl-short','lv-polo','burberry-tee-emblem'].map(pick);
const more=['rl-tee-crew','lacoste-shorts','burberry-polo-check','moncler-short-banho'].map(pick);
const sand=['hermes-slide-colors','sandalia-buckle-black','on-white','lp-loafer-sand'].map(pick);
const houses=['Polo Ralph Lauren','Prada','Moncler','Dior','Lacoste','Louis Vuitton','Burberry','Hermès','Loro Piana','Ami Paris'];
const brandCount=new Set(catalog.map(p=>p.brand)).size,photoCount=catalog.reduce((s,p)=>s+(p.gallery?.length||1),0);
const fmt=n=>n.toLocaleString('pt-BR');
const marquee=houses.map(b=>`<a href="#/colecao/todos?q=${encodeURIComponent(b)}">${esc(b)}</a><i aria-hidden="true">✦</i>`).join('');
return `
<section class="coastal-hero editorial-hero" aria-labelledby="hero-title">
 <div class="hero-atmosphere" aria-hidden="true"><img src="assets/coastal-cover.jpeg" alt="" width="736" height="414"></div>
 <div class="hero-inner">
  <figure class="hero-postcard">
   <img class="campaign-image" src="assets/coastal-cover.jpeg" alt="Arte de uma marina no litoral, com mar azul, barcos e casas coloridas à luz do pôr do sol" width="736" height="414" fetchpriority="high">
   <figcaption><span>THE COASTAL EDIT</span><span>SUMMER / 26</span></figcaption>
  </figure>
  <div class="hero-copy">
   <p class="hero-kicker"><span class="kicker-line"></span>L&T CLUB · SUMMER EDIT</p>
   <h1 id="hero-title"><span>ESSÊNCIA</span><em>de verão.</em></h1>
   <p class="hero-lede">Leveza no vestir, personalidade em cada detalhe. Polos, camisetas, shorts e sandálias para os dias de sol.</p>
   <div class="hero-ctas"><a class="button ivory" href="#/colecao/roupas">Explorar roupas ${icon('arrow')}</a><a class="hero-link" href="#/colecao/todos">Ver toda a coleção ↗</a></div>
   <dl class="hero-facts"><div><dt>${fmt(catalog.length)}</dt><dd>modelos</dd></div><div><dt>${fmt(brandCount)}</dt><dd>grifes</dd></div><div><dt>${fmt(photoCount)}</dt><dd>fotos originais</dd></div></dl>
  </div>
 </div>
 <a class="hero-scroll" href="#collection"><span>Descubra o club</span>${icon('chevron')}</a>
 <svg class="hero-wave" viewBox="0 0 1440 70" preserveAspectRatio="none" aria-hidden="true"><path d="M0 42c120-22 240-34 360-22s240 44 360 44 240-32 360-44 240-2 360 20v30H0z"/></svg>
</section>
<nav class="house-signatures" aria-label="Explore por marca"><div class="marquee-track">${marquee}<span class="marquee-copy" aria-hidden="true">${marquee.replaceAll('<a ','<a tabindex="-1" ')}</span></div></nav>
<section class="club-edit section-space" id="collection"><div class="section-heading"><div><p class="eyebrow">01 · A ESCOLHA DO CLUB</p><h2>Dias de sol.<br><em>Estilo de sobra.</em></h2></div><div class="heading-side"><p>Polos, camisetas e shorts para atravessar o verão com leveza.</p><a class="text-link" href="#/colecao/roupas">Ver todas as roupas ↗</a></div></div><div class="product-grid home-grid rail" tabindex="0" aria-label="Seleção de verão">${garments.map(p=>productCard(p,favorites)).join('')}</div></section>
<section class="wardrobe-chapters section-space"><div class="section-heading"><div><p class="eyebrow">02 · CONSTRUA SUA ASSINATURA</p><h2>O seu <em>repertório.</em></h2></div><span class="chapter-label">SELEÇÃO MASCULINA · L&T</span></div><div class="chapter-grid">
 <a class="chapter-card chapter-tall" href="#/colecao/roupas?q=Polo">${shot(pick('lacoste-polo'),0)}<span class="chapter-index">I.</span><div><small>ESSENCIAIS DO VERÃO</small><h3>Polos &amp;<br>Camisetas</h3><span class="round-arrow">↗</span></div></a>
 <a class="chapter-card" href="#/colecao/roupas?q=Short">${shot(pick('rl-short-light'),0)}<span class="chapter-index">II.</span><div><small>LEVEZA COM IDENTIDADE</small><h3>Shorts &amp;<br>Bermudas</h3><span class="round-arrow">↗</span></div></a>
 <a class="chapter-card" href="#/colecao/tenis?q=Sand">${shot(pick('hermes-slide-colors'),3)}<span class="chapter-index">III.</span><div><small>PÉ NA AREIA</small><h3>Sandálias &amp;<br>Chinelos</h3><span class="round-arrow">↗</span></div></a>
</div></section>
<section class="summer-rail section-space"><div class="section-heading"><div><p class="eyebrow">03 · DO DECK À CIDADE</p><h2>Mais leveza,<br><em>mais presença.</em></h2></div><a class="text-link" href="#/colecao/roupas">Explorar roupas ↗</a></div><div class="product-grid rail" tabindex="0" aria-label="Mais peças de verão">${more.map(p=>productCard(p,favorites)).join('')}</div></section>
<section class="footwear-edit" id="hero-visual"><div class="footwear-stripes" aria-hidden="true"></div><div class="footwear-feature">${shot(pick('hermes-slide-colors'),4,'footwear-shot')}<span class="footwear-tag">HERMÈS · CHINELO H</span></div><div class="footwear-copy"><p class="eyebrow">04 · PÉ NA AREIA</p><h2>Do deck<br><em>à cidade.</em></h2><p>Chinelos, sandálias e tênis leves para completar o visual do verão — dos tons claros às linhas marcantes.</p><a class="button ivory" href="#/colecao/tenis">Explorar calçados ${icon('arrow')}</a><div class="footwear-minis">${sand.map(p=>`<a class="mini-card" href="#/produto/${esc(p.id)}">${shot(p,0)}<span><small>${esc(p.brand)}</small>${esc(p.name)}</span></a>`).join('')}</div></div></section>
<section class="category-section section-space"><div class="section-heading"><div><p class="eyebrow">05 · TODOS OS SEUS DETALHES</p><h2>Escolhas com <em>identidade.</em></h2></div><a class="text-link" href="#/colecao/todos">Toda a coleção ↗</a></div><div class="category-grid">${[{id:'roupas',name:'Roupas',p:pick('rl-polo'),i:1,n:'01'},{id:'tenis',name:'Calçados',p:pick('hermes-tenis-navy'),i:0,n:'02'},{id:'relogios',name:'Relógios',p:pick('chrono-bleu'),i:0,n:'03'},{id:'acessorios',name:'Acessórios',p:pick('rl-cap'),i:1,n:'04'}].map(c=>`<a class="category-card category-${c.id}" href="#/colecao/${c.id}"><span class="category-number">${c.n} · THE CLUB</span>${shot(c.p,c.i)}<div><h3>${c.name}</h3><span>↗</span></div>${c.p.demo?'<small class="example-label">SELEÇÃO DEMONSTRATIVA</small>':''}</a>`).join('')}</div></section>
<section class="club-story"><div class="club-sculpture" aria-hidden="true"><div class="metal-tile"><div class="sculpture-logo">L<span>&amp;</span>T</div><small>CLUB</small></div><span class="monogram-caption">CURADORIA · IDENTIDADE · PRESENÇA</span></div><div class="story-copy"><p class="eyebrow">O CLUB É UMA ATITUDE.</p><h2>O estilo é seu.<br><em>A assinatura também.</em></h2><p>Uma seleção de roupas, calçados e acessórios importados para quem encontra personalidade nos detalhes. Da polo ao short, do corte ao acabamento.</p><a class="text-link light" href="#/colecao/todos">Encontre a sua próxima peça ↗</a></div></section>
<section class="service-strip"><div>${icon('box')}<span><strong>Uma seleção com identidade</strong><small>Roupas, calçados e acessórios em um só lugar.</small></span></div><div>${icon('heart')}<span><strong>Seu próprio repertório</strong><small>Salve favoritos e monte sua seleção.</small></span></div><div>${icon('bag')}<span><strong>Atendimento sob consulta</strong><small>Confirme valores, tamanhos e disponibilidade.</small></span></div></section>`}
export function filtersView(filters){return `<div class="filter-group"><h3>Marca</h3><select name="brand" aria-label="Filtrar por marca"><option value="">Todas as marcas</option>${brands.map(b=>`<option value="${esc(b)}" ${filters.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="filter-group"><h3>Tipo de peça</h3><select name="kind" aria-label="Filtrar por tipo"><option value="">Todos os tipos</option>${kinds.map(k=>`<option value="${esc(k)}" ${filters.kind===k?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="filter-group"><h3>Origem</h3><select name="source" aria-label="Filtrar origem"><option value="">Toda a seleção</option><option value="catalog" ${filters.source==='catalog'?'selected':''}>Dos catálogos da loja</option><option value="demo" ${filters.source==='demo'?'selected':''}>Exemplos demonstrativos</option></select></div><div class="filter-group"><h3>Faixa de preço</h3><div class="price-labels"><span>Até</span><strong class="price-output">${money(filters.maxPrice||1500)}</strong></div><input aria-label="Preço máximo" name="maxPrice" type="range" min="100" max="1500" step="50" value="${esc(filters.maxPrice||1500)}"><div class="range-limits"><span>R$ 100</span><span>R$ 1.500</span></div><p class="filter-hint">Ao reduzir o limite, aparecem apenas peças com preço informado.</p></div><div class="filter-group"><h3>Tamanho</h3><select name="size" aria-label="Filtrar por tamanho"><option value="">Todos os tamanhos</option>${['P','M','G','GG','38','39','40','41','42','43','Único','A confirmar'].map(s=>`<option ${filters.size===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="filter-group"><label class="check-label"><input type="checkbox" name="available" ${filters.available?'checked':''}><span>Com estoque informado</span></label></div><button class="reset-filters" data-action="clear-filters">Limpar filtros ${icon('close')}</button><div class="sidebar-note"><span class="eyebrow">SELEÇÃO DO CATÁLOGO</span><p>Explore as possibilidades.<br>Escolha o que combina com você.</p></div>`}
export function collectionView(products,filters,favorites,{favoritesOnly=false}={}){const current=categories.find(c=>c.id===filters.category)||categories[0];return `<section class="collection-page section-space"><div class="collection-hero"><div class="collection-band" aria-hidden="true"><img src="assets/coastal-cover.jpeg" alt="" width="736" height="414"></div><div class="breadcrumbs"><a href="#/">Início</a><span>/</span><span>${favoritesOnly?'Favoritos':'Coleção'}</span>${current.id!=='todos'?`<span>/</span><span>${current.name}</span>`:''}</div><div class="collection-title"><p class="eyebrow">${favoritesOnly?'SUAS ESCOLHAS, EM UM SÓ LUGAR':'THE CLUB COLLECTION · VOL. 01'}</p><h1>${favoritesOnly?'Seus <em>favoritos.</em>':current.id==='todos'?'Escolhas com <em>presença.</em>':`${current.name} com <em>identidade.</em>`}</h1><p>${favoritesOnly?'A seleção que tem a sua assinatura.':'Essenciais que acompanham você. Explore a seleção L&T Club.'}</p></div></div>${categoryTabs(current.id)}<div class="catalog-toolbar"><span id="results-count">${products.length} ${products.length===1?'produto':'produtos'}</span><div class="catalog-tools"><div class="inline-search">${icon('search')}<input id="catalog-search" aria-label="Buscar nesta coleção" placeholder="Buscar na coleção" value="${esc(filters.query||'')}" type="search"></div><button class="mobile-filters button small outline" data-action="filters">${icon('filter')} Filtros</button><select id="sort" aria-label="Ordenar produtos"><option value="featured">Destaques</option><option value="price-asc" ${filters.sort==='price-asc'?'selected':''}>Menor preço</option><option value="price-desc" ${filters.sort==='price-desc'?'selected':''}>Maior preço</option><option value="name" ${filters.sort==='name'?'selected':''}>Nome: A–Z</option></select></div></div><div class="catalog-layout"><aside class="filters" aria-label="Filtros de produtos">${filtersView(filters)}</aside><div><div class="active-filter-row" id="active-filters"></div><div class="product-grid catalog-grid" id="catalog-grid">${products.length?products.slice(0,24).map(p=>productCard(p,favorites)).join(''):emptyResults(favoritesOnly)}</div><div class="center"><button class="button outline" id="load-more" data-action="load-more" ${products.length>24?'':'hidden'}>Carregar mais produtos ${icon('plus')}</button></div><div class="catalog-end"><span id="shown-count">${products.length} produtos selecionados</span><span>L&T CLUB · ESTILO SEM EXCESSOS</span></div></div></div></section><dialog id="filters-dialog" class="drawer filter-drawer" aria-labelledby="filters-title"><div class="dialog-heading"><h2 id="filters-title">Filtrar coleção</h2><button data-close="filters-dialog" class="icon-button" aria-label="Fechar filtros">${icon('close')}</button></div><div class="mobile-filter-body">${filtersView(filters)}</div><button class="button dark full" data-close="filters-dialog">Ver produtos ${icon('arrow')}</button></dialog>`}
export function emptyResults(favoritesOnly=false){return `<div class="empty-state">${icon(favoritesOnly?'heart':'search')}<h2>${favoritesOnly?'Sua seleção começa aqui.':'Nenhum produto por aqui.'}</h2><p>${favoritesOnly?'Toque no coração dos produtos para guardar seus favoritos.':'Tente outro termo ou ajuste os filtros da coleção.'}</p>${favoritesOnly?'<a class="button dark" href="#/colecao/todos">Explorar coleção ↗</a>':'<button class="button dark" data-action="clear-filters">Limpar filtros</button>'}</div>`}
export function productView(p,products,favorites){if(!p)return `<section class="empty-state not-found"><span class="eyebrow">L&T CLUB · 404</span><h1>Essa peça saiu de cena.</h1><p>O produto não foi encontrado. Explore a coleção para ver outras escolhas.</p><a href="#/colecao/todos" class="button dark">Voltar à coleção ↗</a></section>`;const category=categories.find(c=>c.id===p.category);const g0=p.gallery?.[0]||{image:p.image,width:p.imageWidth,height:p.imageHeight};const related=[...products.filter(x=>x.id!==p.id&&x.brand===p.brand&&x.category===p.category),...products.filter(x=>x.id!==p.id&&x.category===p.category&&x.brand!==p.brand&&!x.demo)].slice(0,4);return `<section class="product-page section-space"><div class="breadcrumbs"><a href="#/">Início</a><span>/</span><a href="#/colecao/${p.category}">${category.name}</a><span>/</span><span>${esc(p.name)}</span></div><div class="product-layout"><div class="product-gallery"><div class="main-product-image ${p.demo?'demo-photo':'catalog-photo'}" id="main-product-image" style="${bgStyle(g0.image)}"><img src="${esc(g0.image)}" alt="${esc(p.name)} — ${esc(p.color)}, ${p.demo?'imagem ilustrativa':'foto do catálogo'}" width="${g0.width||900}" height="${g0.height||900}" fetchpriority="high" style="max-width:${g0.width||1400}px"><span class="product-badge">${esc(p.badge)}</span><button data-action="zoom" class="zoom-button" aria-label="Ampliar fotografia original">${icon('plus')}</button></div><div class="photo-controls"><button data-action="gallery-prev" aria-label="Foto anterior">${icon('back')}</button><span>EXPLORE OS DETALHES · <b id="gallery-counter-mini">1 / ${p.gallery?.length||1}</b></span><button data-action="gallery-next" aria-label="Próxima foto">${icon('arrow')}</button></div><div class="gallery-options" role="group" aria-label="Fotos do produto">${(p.gallery||[{image:p.image,thumbnail:p.image,label:'Foto 1'}]).map((g,i)=>`<button class="gallery-thumb ${i===0?'selected':''}" data-action="gallery" data-index="${i}" aria-label="${esc(g.label)} de ${esc(p.name)}" aria-pressed="${i===0}"><img src="${esc(g.thumbnail)}" alt="" loading="lazy" width="100" height="100"></button>`).join('')}</div><p class="gallery-caption">${p.demo?'IMAGEM ILUSTRATIVA · EXEMPLO DEMONSTRATIVO':'FOTOS ORIGINAIS DO CATÁLOGO'} <span id="gallery-counter">1 / ${p.gallery?.length||1}</span></p></div><div class="product-details"><p class="eyebrow">${esc(p.brand)}</p><h1>${esc(p.name)}</h1><p class="product-lead">${esc(p.description)}</p><div class="detail-price">${money(p.price)}<small>${p.price===null?'Preço a confirmar com a loja':p.demo?'Valor demonstrativo':'Valor informado pela loja'}</small></div><div class="variant-block"><span class="field-label">Cor <strong>${esc(p.color)}</strong></span><span class="selected-swatch" style="--swatch:${esc(p.hex)}" aria-label="Cor ${esc(p.color)}"></span></div><div class="size-heading"><span class="field-label">${p.sizes[0]==='A confirmar'?'Tamanhos a confirmar':p.sizes[0]==='Único'?'Tamanho':'Selecione seu tamanho'}</span><button class="text-link" data-action="size-guide" data-id="${esc(p.id)}">Guia de medidas</button></div><div class="size-options" role="group" aria-label="Tamanhos disponíveis">${p.sizes.map(s=>`<button class="size-option ${p.sizes.length===1?'selected':''}" data-action="size" data-size="${esc(s)}" aria-pressed="${p.sizes.length===1}">${esc(s)}</button>`).join('')}</div><p class="size-error" id="size-error" role="alert"></p><div class="purchase-actions"><button class="button dark add-cart" data-action="add-cart" data-id="${esc(p.id)}" ${p.stock===0?'disabled':''}>${p.stock===0?'Indisponível no momento':'Adicionar à seleção'} ${icon('bag')}</button><button class="button outline detail-favorite ${favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="Salvar ${esc(p.name)} nos favoritos" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button></div><p class="stock-line"><i class="${p.stock===null?'pending':p.stock?'':'out'}"></i>${p.stock===null?'Disponibilidade a confirmar com a loja':p.stock?(p.demo?'Estoque demonstrativo':'Estoque informado'):'Sem estoque'}</p><div class="demo-notice">Esta é uma experiência demonstrativa. Nenhuma compra, cobrança ou envio será realizado.</div><div class="product-accordions"><details open><summary>Detalhes da peça ${icon('plus')}</summary><p>${esc(p.material)}</p><p>${esc(p.fit)}</p></details><details><summary>Entrega e trocas ${icon('plus')}</summary><p>As condições reais de entrega, pagamento e troca serão informadas pela L&T Club quando a loja estiver pronta para vendas. Nesta vitrine, você pode apenas simular uma seleção.</p></details><details><summary>Cuidados e conservação ${icon('plus')}</summary><p>Consulte a etiqueta e as instruções do fabricante do produto real. Composição, numeração e especificações devem ser confirmadas com a loja.</p></details></div></div></div><section class="related-products"><div class="section-heading"><div><p class="eyebrow">COMPLETE A SUA SELEÇÃO</p><h2>Combina com <em>você.</em></h2></div><a class="text-link" href="#/colecao/${esc(p.category)}">Ver ${esc(category.name.toLowerCase())} ↗</a></div><div class="product-grid rail" tabindex="0" aria-label="Peças relacionadas">${related.map(x=>productCard(x,favorites)).join('')}</div></section></section>`}
export function cartView(cart,products,step='cart'){const lines=cart.map(l=>({line:l,product:products.find(p=>p.id===l.id)})).filter(x=>x.product);const total=cartTotal(cart,products);if(step==='success')return `<div class="dialog-heading"><h2 id="cart-title">Sua seleção</h2><button data-close="cart-dialog" class="icon-button" aria-label="Fechar sacola">${icon('close')}</button></div><div class="cart-success"><span class="success-circle">${icon('check')}</span><p class="eyebrow">SELEÇÃO CONCLUÍDA</p><h3>Bom gosto.<br>Boa escolha.</h3><p>A simulação foi concluída. Nenhum pedido foi enviado, nenhum pagamento foi feito e nenhum dado foi compartilhado.</p><button class="button dark full" data-close="cart-dialog">Continuar explorando ↗</button></div>`;
return `<div class="dialog-heading"><div><p class="eyebrow">L&T CLUB</p><h2 id="cart-title">${step==='review'?'Revise sua seleção.':'Sua sacola.'} <span>(${lines.reduce((s,x)=>s+x.line.quantity,0)})</span></h2></div><button data-close="cart-dialog" class="icon-button" aria-label="Fechar sacola">${icon('close')}</button></div>${!lines.length?`<div class="empty-state cart-empty">${icon('bag')}<h3>Espaço para<br>seu próximo essencial.</h3><p>Sua sacola ainda está vazia.</p><a class="button dark" href="#/colecao/todos">Explorar coleção ↗</a></div>`:`<div class="cart-lines">${lines.map(({line:l,product:p})=>`<article class="cart-line"><a href="#/produto/${esc(p.id)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="120" height="140"></a><div class="cart-line-info"><span class="product-brand">${esc(p.brand)}</span><h3><a href="#/produto/${esc(p.id)}">${esc(p.name)}</a></h3><p>${esc(p.color)} · ${esc(l.size)}</p><strong>${p.price===null?'Sob consulta':money(p.price*l.quantity)}</strong>${step==='cart'?`<div class="quantity-row"><div class="quantity-control"><button data-action="quantity" data-id="${esc(p.id)}" data-size="${esc(l.size)}" data-quantity="${l.quantity-1}" aria-label="Diminuir quantidade de ${esc(p.name)}">${icon('minus')}</button><span>${l.quantity}</span><button data-action="quantity" data-id="${esc(p.id)}" data-size="${esc(l.size)}" data-quantity="${l.quantity+1}" aria-label="Aumentar quantidade de ${esc(p.name)}">${icon('plus')}</button></div><button class="remove-item" data-action="quantity" data-id="${esc(p.id)}" data-size="${esc(l.size)}" data-quantity="0">Remover</button></div>`:`<small>Quantidade: ${l.quantity}</small>`}</div></article>`).join('')}</div><div class="cart-summary"><div><span>${lines.some(x=>x.product.price===null)?'Valores pendentes':'Subtotal'}</span><strong>${lines.some(x=>x.product.price===null)?'Sob consulta':money(total)}</strong></div><p>Produtos do catálogo estão sob consulta. Exemplos têm valores ilustrativos. Nenhum pagamento é realizado.</p><div class="demo-notice">${step==='review'?'Ao concluir, você apenas encerra uma simulação local. Nenhum pedido será enviado.':'Sua seleção fica apenas neste navegador.'}</div><button class="button dark full" data-action="${step==='review'?'finish-demo':'review-cart'}">${step==='review'?'Concluir simulação':'Revisar seleção'} ${icon('arrow')}</button>${step==='review'?'<button class="back-to-cart" data-action="cart">Voltar à sacola</button>':'<button class="back-to-cart" data-close="cart-dialog">Continuar explorando</button>'}</div>`}`}
